-- PropBetEdge — Women's Basketball History
-- Wikidata CC0 P54 evidence for canonical WNBA teams. Evidence only; not a season-roster endpoint.
begin;
do $seed$
declare
  v_doc uuid;
  v_run uuid;
  v_existing integer;
begin
  perform public.wbh_assert_ingestible('wikidata');
  select count(*) into v_existing from public.wbh_ingestion_runs where scope->>'dataset'='wikidata_wnba_team_memberships_v1' and status='ok';
  if v_existing > 0 then
    if (select count(*) from public.wbh_person_team_membership_claims) >= 982 then return; end if;
    raise exception 'wbh: P54 membership run exists but evidence counts are incomplete; refusing implicit repair' using errcode='P0001';
  end if;
  values ('wikidata','wikidata:P54:canonical_wnba_team_memberships_v1','https://query.wikidata.org/sparql + https://www.wikidata.org/w/api.php','GET','2026-09-16T10:57:10Z',200,'42700afadffd2a8716f141aa2760e192f779f502f6c5f225d6b9515b3733386f','application/json',653862,'hash_only','wbh_wikidata_wnba_membership_v1','Length-framed raw Wikidata responses were hashed and not retained; normalized CC0 P54 statements are committed in the manifest.') returning document_id into v_doc;
  values ('wikidata','wikidata_p54_wnba_membership','1.0.0','wbh_wikidata_wnba_membership_v1','ingest','2026-09-16T10:57:10Z',jsonb_build_object('dataset','wikidata_wnba_team_memberships_v1','claims',982,'people_with_claims',633,'qualified_overlap_2024',59,'undated_claims',698,'raw_capture_sha256','42700afadffd2a8716f141aa2760e192f779f502f6c5f225d6b9515b3733386f')) returning run_id into v_run;
  update public.wbh_ingestion_runs set status='ok', counts=jsonb_build_object('claims',982,'people_with_claims',633,'dated_claims',284,'undated_claims',698,'qualified_overlap_2024',59,'outside_2024',225,'by_team','{"tm_atlanta_dream":73,"tm_chicago_sky":83,"tm_new_york_liberty":108,"tm_connecticut_sun":81,"tm_phoenix_mercury":108,"tm_los_angeles_sparks":109,"tm_washington_mystics":102,"tm_minnesota_lynx":117,"tm_seattle_storm":89,"tm_indiana_fever":78,"tm_dallas_wings":24,"tm_las_vegas_aces":10}'::jsonb) where run_id=v_run;
end $seed$;
commit;
